'use client'

import { useState, useEffect } from 'react'
import Image from 'next/image' // <--- Importado para el logo
import { createClient } from '@/lib/supabase/client'
import { useRouter } from 'next/navigation'
import { EyeIcon, EyeSlashIcon } from '@heroicons/react/24/outline'

export default function LoginPage() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const router = useRouter()
  const supabase = createClient()

  // Verificar si ya hay sesión activa y escuchar cambios
  useEffect(() => {
    const checkSession = async () => {
      const { data: { session } } = await supabase.auth.getSession()
      if (session) {
        const { data: profile } = await supabase
          .from('usuarios')
          .select('rol')
          .eq('id', session.user.id)
          .single()
        
        redirectUser(profile?.rol)
      }
    }
    checkSession()

    // Escuchar cambios de sesión (por si el usuario cierra sesión o se loguea en otra pestaña)
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const getProfile = async () => {
          const { data: profile } = await supabase
            .from('usuarios')
            .select('rol')
            .eq('id', session.user.id)
            .single()
          
          redirectUser(profile?.rol)
        }
        getProfile()
      }
    })

    return () => subscription.unsubscribe()
  }, [])

  const redirectUser = (rol: string | undefined) => {
    if (rol === 'admin') router.push('/admin')
    else if (rol === 'bodeguero') router.push('/bodeguero/')
    else if (rol === 'vendedor') router.push('/vendedor/')
   else if (rol === 'cartera') router.push('/cartera/')
    else router.push('/dashboard')
  }

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    // Validaciones básicas
    if (!email || !password) {
      setError('Por favor, completa todos los campos')
      setLoading(false)
      return
    }

    try {
      const { data, error } = await supabase.auth.signInWithPassword({ 
        email, 
        password 
      })

      if (error) {
        if (error.message.includes('Invalid login credentials')) {
          setError('Credenciales incorrectas. Verifica tu email y contraseña.')
        } else {
          setError(error.message)
        }
        setLoading(false)
        return
      }

      // Obtener el rol del usuario
      const { data: profile, error: profileError } = await supabase
        .from('usuarios')
        .select('rol, nombre')
        .eq('id', data.user.id)
        .single()

      if (profileError || !profile) {
        setError('Error al obtener los datos del usuario')
        setLoading(false)
        return
      }

      // Redirigir según el rol
      redirectUser(profile.rol)

    } catch (error) {
      console.error('Error en login:', error)
      setError('Ocurrió un error inesperado')
      setLoading(false)
    }
  }

  return (
    <div className="login-page-bg">
      <div className="login-card">
        {/* Logo corregido con Next/Image */}
         <div style={{ textAlign: 'center', marginBottom: '24px' }}>
          <img 
            src="data:image/png;base64," 
            alt="Logo Mobulaa" 
            style={{ 
              width: '550px', 
              height: 'auto', 
              display: 'inline-block' 
            }} 
          />
        </div>
        
        <h1 className="text-2xl font-bold mb-2 text-center" style={{ color: '#232323' }}>
          ¡Bienvenido!
        </h1>
        
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-lg mb-4 text-sm">
            {error}
          </div>
        )}
        
        <form onSubmit={handleLogin}>
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Correo electrónico
            </label>
            <input 
              className="input-mobulaa" 
              type="email" 
              placeholder="ejemplo@mobulaa.com" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              disabled={loading}
              autoComplete="email"
            />
          </div>
          
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Contraseña
            </label>
            <div className="relative">
              <input 
                className="input-mobulaa pr-10" 
                type={showPassword ? "text" : "password"} 
                placeholder="••••••••" 
                value={password} 
                onChange={e => setPassword(e.target.value)} 
                disabled={loading}
                autoComplete="current-password"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700"
              >
                {showPassword ? (
                  <EyeSlashIcon className="w-5 h-5" />
                ) : (
                  <EyeIcon className="w-5 h-5" />
                )}
              </button>
            </div>
          </div>
          
          <button 
            type="submit" 
            className="btn-mobulaa"
            disabled={loading}
          >
            {loading ? (
              <div className="flex items-center justify-center gap-2">
                <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                Iniciando sesión...
              </div>
            ) : (
              'Ingresar'
            )}
          </button>
        </form>
        
        <div className="mt-6 flex items-center justify-between text-sm">
          <div className="flex items-center">
            <input
              type="checkbox"
              id="remember"
              className="w-4 h-4 text-[#1A0087] border-gray-300 rounded focus:ring-[#1A0087]"
            />
            <label htmlFor="remember" className="ml-2 text-gray-600">
              Recordarme
            </label>
          </div>
          <a href="/recuperar-password" className="text-[#1A0087] font-medium hover:underline">
            ¿Olvidaste tu contraseña?
          </a>
        </div>
        
        
        <p className="text-center mt-6 text-sm text-gray-600">
          ¿No tienes cuenta?{' '}
          <a href="/registro" className="text-[#1A0087] font-bold hover:underline">
            Regístrate
          </a>
        </p>
        
        <div className="mt-6 pt-4 border-t border-gray-200 text-center">
          <p className="text-xs text-gray-400">

            © 2024 Mobulaa. Todos los derechos reservados.
          </p>
        </div>
      </div>
    </div>
  )
}